namespace ApiRequest;
class Program
{
    public async Task Main()
    {
        var httpClient = new HttpClient();
        var url = "https://api.spryng.nl/v2/contacts/filter";

        url += "?AccountReference=String&GroupId=Array&Destination=String&OptOutStatus=String&AddressType=String&MetadataKey=String&MetadataValue=String&Search=String&ContactOwnership=String&SortBy=String&SortOrder=String&PageNo=Integer&PageSize=Integer";

        var request = new HttpRequestMessage(HttpMethod.Parse("GET"), url);

        request.Headers.Add("AccountReference", "your-AccountReference-header-here");
        request.Headers.Add("X-Api-Key", "YOUR_KEY_HERE");


        var response = await httpClient.SendAsync(request);

        if(response.IsSuccessStatusCode)
        {
            var responseBody = await response.Content.ReadAsStringAsync();
            Console.WriteLine("Response: " + responseBody);
        }
        else
        {
            Console.WriteLine($"Error: {response.StatusCode}");
            var errorContent = await response.Content.ReadAsStringAsync();
            Console.WriteLine("Error details: " + errorContent);
        }
    }
}
